insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('f21cfef3-1e8d-4d8c-b00e-368137a06d78', '74db908e-ea97-4fcc-a7ee-90462e73da04', $$intro: kattenkruid veroorzaakt opwinding bij katten door nepetalactonen$$,
   $$biologie-vwo-2026-ii-opwinding-door-kattenkruid-context1.png$$,
   $$Veel katten raken opgewonden als ze afbeelding 1 kattenkruid ruiken (afbeelding 1). De geur van kattenkruid wordt veroorzaakt door stoffen (nepetalactonen) die de plant produceert als afweer tegen insecten.$$, 'inline'),
  ('1cdda6f6-3cf5-49a6-a5ea-87fc43daccac', '74db908e-ea97-4fcc-a7ee-90462e73da04', $$stamboom van katten met wel/niet reageren op kattenkruid (afbeelding 2)$$,
   $$biologie-vwo-2026-ii-opwinding-door-kattenkruid-context2.png$$,
   $$Wetenschappers onderzochten de reactie op kattenkruid van katten die familie van elkaar zijn. Met de gegevens stelden ze een stamboom op (afbeelding 2). Daaruit leidden ze af dat de reactie op kattenkruid een autosomale dominante eigenschap is die wordt veroorzaakt door één gen.
afbeelding 2$$, 'inline'),
  ('28ac3776-d9c7-4df5-a3ed-5b9652fcfa49', '74db908e-ea97-4fcc-a7ee-90462e73da04', $$laatste stappen van nepetalactonenaanmaak met enzymen ISY en NEPS (afbeelding 3)$$,
   $$biologie-vwo-2026-ii-opwinding-door-kattenkruid-context3.png$$,
   $$Voor de aanmaak van de nepetalactonen heeft kattenkruid verschillende enzymen. Afbeelding 3 geeft de laatste stappen weer van de aanmaak van nepetalactonen met de daarbij betrokken enzymen ISY en NEPS.
afbeelding 3$$, 'inline'),
  ('6d2674b7-91c0-474a-81ec-416c0e888736', '74db908e-ea97-4fcc-a7ee-90462e73da04', $$fylogenetische stamboom van lipbloemigen en ISY-enzymproductie (afbeelding 4)$$,
   $$biologie-vwo-2026-ii-opwinding-door-kattenkruid-context4.png$$,
   $$Kattenkruid behoort tot de lipbloemigen. Ook basilicum, munt en rozemarijn horen bij deze familie. Bij een voorouder van kattenkruid is het ISY-gen door een deletie verloren gegaan. Hierdoor kan een deel van de lipbloemigen geen nepetalactonen aanmaken. Kattenkruid heeft de mogelijkheid om het ISY-enzym te produceren opnieuw verkregen. Afbeelding 4 is een fylogenetische stamboom van een aantal soorten uit de lipbloemigenfamilie. Daarin is aangegeven welke soorten het ISY- enzym produceren.
afbeelding 4$$, 'inline'),
  ('a45360b0-5d2e-4fb8-ab61-2e95dcc3436c', '74db908e-ea97-4fcc-a7ee-90462e73da04', $$ontstaan van het ISY-gen uit de P5βR-locus en NEPS-locus (afbeelding 5)$$,
   $$biologie-vwo-2026-ii-opwinding-door-kattenkruid-context5.png$$,
   $$Afbeelding 5 laat zien hoe bij kattenkruid een nieuw ISY-gen is ontstaan. Hierbij waren twee loci betrokken: de P5βR-locus en de NEPS-locus. Ongeveer 20 miljoen jaar geleden trad een verdubbeling op in de P5βR- locus. In de 10 miljoen jaar daarna is door veranderingen in de coderende sequenties het Anc3-gen ontstaan. Het Anc3-gen werd daarna gekopieerd en verplaatst naar de NEPS-locus. Door nog enkele veranderingen in de coderende gebieden is het ISY-gen ontstaan.
afbeelding 5$$, 'inline'),
  ('83ddba89-1b2e-43df-bf0c-423db318533f', '74db908e-ea97-4fcc-a7ee-90462e73da04', $$uitwerkbijlage: kopie van de fylogenetische stamboom met cirkels$$,
   $$biologie-vwo-2026-ii-opwinding-door-kattenkruid-context6.png$$,
   $$4$$, 'uitwerkbijlage'),
  ('ed2d2c4d-bd09-4df4-9106-bdde0f1c1830', '04c0b36f-e309-4fe2-9908-8a1059c98af8', $$intro: waterspreeuw gesignaleerd in dierentuin Emmen$$,
   $$biologie-vwo-2026-ii-waterspreeuw-duikt-op-in-dierentuin-context1.png$$,
   $$In het buitenverblijf van de olifanten in de dierentuin in Emmen is ’s winters soms een waterspreeuw te zien. Dat is bijzonder, omdat de soort in Nederland nauwelijks voorkomt.$$, 'inline'),
  ('7eb4f3a7-c06a-47ea-9fc3-f5c0669f7523', '04c0b36f-e309-4fe2-9908-8a1059c98af8', $$waterspreeuw: leefgebied, verspreiding in Nederland en voedsel (afbeelding 1, 2)$$,
   $$biologie-vwo-2026-ii-waterspreeuw-duikt-op-in-dierentuin-context2.png$$,
   $$De waterspreeuw (Cinclus cinclus, afbeelding 1) is een kleine zwarte zangvogel met een witte borst en een bruine kop. De vogel komt van nature vooral voor rond beken met helder, snelstromend water. In Nederland is hij zeer zeldzaam. De vogel wordt het meest waargenomen in Zuid-Limburg (afbeelding 2).
afbeelding 1 afbeelding 2
De waterspreeuw eet voornamelijk de larven van haften, steenvliegen en schietmotten. Deze larven leven van de algen in het water. De larven worden ook gegeten door kleine visjes. De waterspreeuw eet ook kleine visjes.$$, 'inline'),
  ('66d76fa5-c2b2-4023-b348-5734b61d8dc7', '04c0b36f-e309-4fe2-9908-8a1059c98af8', $$larven van haften/steenvliegen/schietmotten zijn indicatorsoorten voor waterkwaliteit$$,
   $$biologie-vwo-2026-ii-waterspreeuw-duikt-op-in-dierentuin-context3.png$$,
   $$De larven van haften, steenvliegen en schietmotten zijn indicatorsoorten voor waterkwaliteit, omdat ze gevoelig zijn voor vervuiling. De waterspreeuw is geen betrouwbare indicatorsoort in Nederland.$$, 'inline'),
  ('9b06bc8b-d261-4fa2-bbb5-30ba09404a73', '04c0b36f-e309-4fe2-9908-8a1059c98af8', $$uitspraken over waterspreeuw en het voedselweb$$,
   $$biologie-vwo-2026-ii-waterspreeuw-duikt-op-in-dierentuin-context4.png$$,
   $$Hieronder staan uitspraken over de waterspreeuw en het beschreven voedselweb.
1 De waterspreeuw behoort tot de consumenten van de 1e orde.
2 Het snelstromende water behoort tot de habitat van de waterspreeuw.
3 De kans op accumulatie van persistente gifstoffen in waterspreeuwen is groter wanneer ze visjes eten, dan wanneer ze larven eten.$$, 'inline'),
  ('8d5111f7-0f63-4642-b7d5-a094a3f851ec', '04c0b36f-e309-4fe2-9908-8a1059c98af8', $$hemoglobinegehalte waterspreeuw vs. zanglijster en zuurstofverzadigingscurve (afbeelding 3)$$,
   $$biologie-vwo-2026-ii-waterspreeuw-duikt-op-in-dierentuin-context5.png$$,
   $$De waterspreeuw kan bij het jagen een halve minuut onder water blijven. Dit is mogelijk doordat hij meer hemoglobine in het bloed heeft dan verwante soorten, zoals de zanglijster. Zie de tabel hieronder.
gehalte hemoglobine (gram per 100 mL bloed) waterspreeuw 19 zanglijster 16
Afbeelding 3 is een zuurstofverzadigingscurve. Deze geldt voor beide vogelsoorten.
afbeelding 3$$, 'inline'),
  ('34482ef4-741a-4706-a9e8-aed9f518406c', '04c0b36f-e309-4fe2-9908-8a1059c98af8', $$zuurstofspanning in longen en spierweefsel van de zanglijster$$,
   $$biologie-vwo-2026-ii-waterspreeuw-duikt-op-in-dierentuin-context6.png$$,
   $$De zanglijster heeft op een bepaald moment de volgende zuurstofspanning in longen en spierweefsel:
− pO2 longen: 12 kPa
− pO2 spierweefsel: 6 kPa Neem aan dat het bloed van de zanglijster 20 mL zuurstof per 100 mL bloed bevat bij een zuurstofverzadiging van 100%.$$, 'inline'),
  ('ab7241c6-3ca0-4d91-bea9-3750c039c567', '04c0b36f-e309-4fe2-9908-8a1059c98af8', $$tijdens duiken neemt de pCO2 in de weefsels van de waterspreeuw toe$$,
   $$biologie-vwo-2026-ii-waterspreeuw-duikt-op-in-dierentuin-context7.png$$,
   $$Wanneer de waterspreeuw onder water aan het jagen is, neemt de pCO2 in de weefsels toe.$$, 'inline'),
  ('2c4cd124-a2c0-4243-8ae6-cbb6819d7930', '04c0b36f-e309-4fe2-9908-8a1059c98af8', $$waterspreeuw gebruikt vleugels en staart bij het jagen onder water$$,
   $$biologie-vwo-2026-ii-waterspreeuw-duikt-op-in-dierentuin-context8.png$$,
   $$Als een waterspreeuw jaagt, loopt hij over de bodem en gebruikt hij zijn vleugels om vooruit te komen. Zijn staart gebruikt hij daarbij als roer.$$, 'inline'),
  ('7c7f4e8a-a04d-4609-b227-ad10a34ab763', '04c0b36f-e309-4fe2-9908-8a1059c98af8', $$hartslagdaling en vaatvernauwing bij de duikende waterspreeuw$$,
   $$biologie-vwo-2026-ii-waterspreeuw-duikt-op-in-dierentuin-context9.png$$,
   $$Onder water daalt de hartslagfrequentie van de waterspreeuw. Ook trekken de spiertjes rond de slagadertjes van de huid en de poten samen. Hieronder staan uitspraken over deze regulatie.
1 Deze regulatie leidt ertoe dat de huid en poten kouder worden.
2 Deze regulatie wordt veroorzaakt door het animale zenuwstelsel.
3 Het samentrekken van de spiertjes rond de slagadertjes van de huid en de poten is onderdeel van een reflexboog.$$, 'inline'),
  ('e802bceb-5913-47af-b0ba-a25c4329b18b', '04c0b36f-e309-4fe2-9908-8a1059c98af8', $$lagere stofwisseling onder water stelt de ademprikkel uit$$,
   $$biologie-vwo-2026-ii-waterspreeuw-duikt-op-in-dierentuin-context10.png$$,
   $$Onder water daalt ook de stofwisseling van de waterspreeuw sterk. Hierdoor wordt de ademprikkel uitgesteld en kan de waterspreeuw langer onder water blijven.$$, 'inline'),
  ('f7da3a79-7441-4cba-8059-f824946394e0', '04c0b36f-e309-4fe2-9908-8a1059c98af8', $$waterspreeuw als enige zangvogel die onder water zwemt; vergelijking met andere vogels$$,
   $$biologie-vwo-2026-ii-waterspreeuw-duikt-op-in-dierentuin-context11.png$$,
   $$De waterspreeuw is de enige zangvogel die onder water zwemt. Er zijn wel andere vogels die onder water kunnen zwemmen, zoals pinguïns en papegaaiduikers. Ook bij de stormvogels komen geslachten (genera) voor die dit kunnen. Deze vogels hebben – net als waterspreeuwen – eigenschappen die het mogelijk maken om onder water te zwemmen, zoals een extra dicht verenkleed. De andere geslachten stormvogels hebben deze eigenschappen niet.$$, 'inline'),
  ('688a01c4-3675-45b5-b68b-d241d56c006b', '7274a52f-25fa-442d-b11e-8d17f5c97ded', $$intro: rol van vitamine D voor het immuunsysteem$$,
   $$biologie-vwo-2026-ii-vitamine-d-context1.png$$,
   $$Onderzoekers ontdekken steeds meer over de rol van vitamine D voor ons immuunsysteem. Veel mensen hebben een gebrek aan deze vitamine.$$, 'inline'),
  ('bc246568-4789-4a6b-bd27-2fe701c5003b', '7274a52f-25fa-442d-b11e-8d17f5c97ded', $$aanmaak en omzetting van vitamine D2/D3 tot calcidiol en calcitriol (afbeelding 1)$$,
   $$biologie-vwo-2026-ii-vitamine-d-context2.png$$,
   $$De vetoplosbare vitamines D2 en D3 zijn belangrijk voor mensen. Vitamine D2 zit in planten en schimmels, en vitamine D3 in dierlijke producten. Vitamine D3 wordt ook aangemaakt uit provitamine D3 wanneer de huid wordt blootgesteld aan ultraviolette straling. Provitamine D3 wordt gevormd uit cholesterol. In de lever worden vitamine D2 en D3 beide omgezet in calcidiol. De nieren zetten die stof vervolgens om in calcitriol. Zie afbeelding 1.
afbeelding 1$$, 'inline'),
  ('817ec084-1f0c-4507-b361-6c6fdbca6b03', '7274a52f-25fa-442d-b11e-8d17f5c97ded', $$vervoer van vitamine D3 via het bloed en via chylomicronen/lymfe naar de lever$$,
   $$biologie-vwo-2026-ii-vitamine-d-context3.png$$,
   $$De vitamine D3 die wordt aangemaakt in de huid, wordt via het bloed naar de lever vervoerd. De vitamine D3 die wordt opgenomen in de darmen, wordt voornamelijk vervoerd in chylomicronen (vetbolletjes). Deze worden eerst via de lymfe en vervolgens via het bloed vervoerd naar de lever.$$, 'inline'),
  ('706e083e-b973-4040-bc10-66530461ff05', '7274a52f-25fa-442d-b11e-8d17f5c97ded', $$werking van de vitamine D-receptor (VDR) en VDRE bij genexpressie (afbeelding 2)$$,
   $$biologie-vwo-2026-ii-vitamine-d-context4.png$$,
   $$Bijna alle cellen van het lichaam hebben vitamine D-receptoren. Calcitriol uit het bloed bindt aan een vitamine D-receptor (VDR) in de cel. VDR transporteert calcitriol naar de kern. Daar vormt het een complex met cofactoren. Dit complex bindt aan het vitamine D-respons-element (VDRE). Op deze manier wordt de expressie van bepaalde doelgenen gereguleerd. Zie afbeelding 2.
afbeelding 2$$, 'inline'),
  ('bf340545-01ef-4a3c-b6ad-6a01614010e4', '7274a52f-25fa-442d-b11e-8d17f5c97ded', $$celkweekonderzoek naar effecten van vitamine D door genen uit te schakelen$$,
   $$biologie-vwo-2026-ii-vitamine-d-context5.png$$,
   $$Wetenschappers proberen de effecten van vitamine D op specifieke cellen op te helderen door in het laboratorium onderzoek te doen aan celkweken. Ze doen dit door bepaalde genen in de cellen uit te schakelen, en daarna calcitriol toe te dienen aan de cellen in de kweek. De effecten worden vergeleken met de effecten van toediening van calcitriol aan cellen met intacte genen. Hieronder staan drie genen.
1 het gen voor DBP
2 het gen voor VDR
3 het gen voor het enzym dat calcidiol omzet in calcitriol.$$, 'inline'),
  ('4517be5a-d51a-41d7-acb5-4ea450bf808d', '7274a52f-25fa-442d-b11e-8d17f5c97ded', $$schematische weergave van de calciumregulatie (nog niet compleet)$$,
   $$biologie-vwo-2026-ii-vitamine-d-context6.png$$,
   $$Een van de functies van calcitriol is de regeling van de calciumhomeostase. Hierbij zijn meerdere hormonen en organen betrokken. Hieronder staat een schematische weergave van de calciumregulatie. Het schema is nog niet compleet.$$, 'inline'),
  ('b048b894-5e88-4794-b2ef-2d91d8e361f1', '7274a52f-25fa-442d-b11e-8d17f5c97ded', $$invloed van calcitriol op afweercellen en T-celdifferentiatie (afbeelding 3)$$,
   $$biologie-vwo-2026-ii-vitamine-d-context7.png$$,
   $$In afbeelding 3 is te zien dat calcitriol de activiteit van bepaalde afweercellen beïnvloedt. Eén cel is aangegeven met de letter P. Ook beïnvloedt calcitriol de differentiatie van geactiveerde T-cellen. Bij voldoende calcitriol is er een goede balans tussen T-cellen die ontstekingsstimulerende cytokinen afgeven en T-cellen die ontstekingsremmende cytokinen afgeven. Zo kan het afweersysteem reageren op ziekteverwekkers, zonder dat het risico op aanvallen op eigen lichaamscellen stijgt.
afbeelding 3$$, 'inline'),
  ('099770b8-7f58-4b94-bebd-9c34c8e4701a', '7274a52f-25fa-442d-b11e-8d17f5c97ded', $$cel P behoort tot de aangeboren afweer; dendritische cel presenteert antigeen$$,
   $$biologie-vwo-2026-ii-vitamine-d-context8.png$$,
   $$Cel P behoort tot de aangeboren afweer. De dendritische cel (APC) presenteert antigenen aan een T-helpercel.$$, 'inline'),
  ('5380f530-0dfd-46f6-b5af-df316e2f3c9f', '750ffe83-9b39-4dff-9d23-8393c53598ff', $$intro: eerste crispr-cas-behandeling van erfelijk oedeem door Danny Cohn$$,
   $$biologie-vwo-2026-ii-moleculair-gereedschap-tegen-erfelijk-oedeem-context1.png$$,
   $$In 2022 behandelde Danny Cohn als eerste arts in Nederland een patiënt met erfelijk oedeem met crispr-cas. De patiënt kon dezelfde dag al het UMC te Amsterdam verlaten.$$, 'inline'),
  ('725f6ff7-6a1a-464e-bccb-83788766093b', '750ffe83-9b39-4dff-9d23-8393c53598ff', $$HAE-1: erfelijke aandoening met aanvallen van zwellingen (afbeelding 1)$$,
   $$biologie-vwo-2026-ii-moleculair-gereedschap-tegen-erfelijk-oedeem-context2.png$$,
   $$Hereditair angio-oedeem type 1 (HAE-1) is een zeldzame erfelijke aandoening. De aandoening veroorzaakt aanvallen van zwellingen bij stress of infectie. Deze zwellingen kunnen op allerlei plaatsen ontstaan, bijvoorbeeld in het gezicht, de handen, of de darmen. Afbeelding 1 laat zien hoe een aanval rond de mond zich ontwikkelt. Zo’n aanval duurt gemiddeld drie dagen.
afbeelding 1$$, 'inline'),
  ('8b3ab0b9-abbf-456e-9981-ef7b2df0cee6', '750ffe83-9b39-4dff-9d23-8393c53598ff', $$andere mogelijke oorzaken van oedeem$$,
   $$biologie-vwo-2026-ii-moleculair-gereedschap-tegen-erfelijk-oedeem-context3.png$$,
   $$Oedeem kan ook andere oorzaken hebben. Hieronder staan drie situaties.
1 een lage bloeddruk
2 een hoge colloïd-osmotische waarde van het bloed
3 een verstopping van de lymfevaten$$, 'inline'),
  ('c725a4e4-07f2-4b2b-858c-020a62b1c9ee', '750ffe83-9b39-4dff-9d23-8393c53598ff', $$opgezwollen darmslijmvlies veroorzaakt buikpijn en diarree$$,
   $$biologie-vwo-2026-ii-moleculair-gereedschap-tegen-erfelijk-oedeem-context4.png$$,
   $$Als het darmslijmvlies is opgezwollen, ontstaan aanvallen van ernstige buikpijn. De patiënt heeft dan ook last van diarree (waterige ontlasting).$$, 'inline'),
  ('7ea403ca-b55a-4800-8191-9d401840cc35', '750ffe83-9b39-4dff-9d23-8393c53598ff', $$HAE-1 erft autosomaal dominant over$$,
   $$biologie-vwo-2026-ii-moleculair-gereedschap-tegen-erfelijk-oedeem-context5.png$$,
   $$HAE-1 erft autosomaal dominant over.$$, 'inline'),
  ('984186cb-17ef-49e5-a29b-08da5349d39d', '750ffe83-9b39-4dff-9d23-8393c53598ff', $$allelfrequentie van HAE-1 in Nederland$$,
   $$biologie-vwo-2026-ii-moleculair-gereedschap-tegen-erfelijk-oedeem-context6.png$$,
   $$De frequentie van het allel dat HAE-1 veroorzaakt, is in Nederland 0,000028. Ga ervan uit dat de wet van Hardy-Weinberg van toepassing is en dat Nederland 18 miljoen inwoners heeft.$$, 'inline'),
  ('0938b467-2d72-4a41-b82d-2540f0fc56e5', '750ffe83-9b39-4dff-9d23-8393c53598ff', $$C1-esteraseremmer remt het kininesysteem en de vorming van weefselvloeistof$$,
   $$biologie-vwo-2026-ii-moleculair-gereedschap-tegen-erfelijk-oedeem-context7.png$$,
   $$Bij HAE-1 is er een mutatie in het gen voor C1-esteraseremmer. Hierdoor is er een verminderde activiteit van C1-esteraseremmer. Deze stof is een remmer van het kininesysteem, en wordt geproduceerd door levercellen. Het kininesysteem beïnvloedt de vorming van weefselvloeistof.$$, 'inline'),
  ('10063196-eeb1-450c-a3cf-b78ca5b8a19c', '750ffe83-9b39-4dff-9d23-8393c53598ff', $$uitspraken over spontane mutaties die HAE-1 veroorzaken$$,
   $$biologie-vwo-2026-ii-moleculair-gereedschap-tegen-erfelijk-oedeem-context8.png$$,
   $$In een kwart van de gevallen is er sprake van een spontane mutatie. Hieronder staan uitspraken over deze spontane mutaties.
1 Een puntmutatie die HAE-1 veroorzaakt, leidt tot een verandering in de primaire structuur van het eiwit.
2 Een mutatie in één allel is voldoende om een verminderde activiteit van C1-esteraseremmer te krijgen in de betreffende cel.
3 Het ontstaan van een spontane mutatie in een volledig gedifferentieerde levercel leidt bij een volwassen persoon tot HAE-1.$$, 'inline'),
  ('bd946e84-0f26-46b5-9d14-c3f554dcd2e4', '750ffe83-9b39-4dff-9d23-8393c53598ff', $$omzettingen van factor XII, prekallikreïne en kininogeen tot bradykinine$$,
   $$biologie-vwo-2026-ii-moleculair-gereedschap-tegen-erfelijk-oedeem-context9.png$$,
   $$Bij de vorming van weefselvloeistof zijn ook de stoffen factor XII, prekallikreïne en kininogeen betrokken. In het bloedplasma vinden verschillende omzettingen plaats:
− Een prikkel, zoals stress of een infectie, activeert factor XII.
− Geactiveerde factor XII zet prekallikreïne om in kallikreïne.
− Kallikreïne knipt kininogeen waarbij het eiwit bradykinine ontstaat.
− Bradykinine bindt zich vervolgens aan bradykinine-receptoren op endotheelcellen. Hierdoor wijken deze cellen uiteen en lekt vocht vanuit het bloedvat naar het omliggende weefsel.
− Kallikreïne activeert factor XII waardoor uiteindelijk meer bradykinine wordt aangemaakt. In gezonde mensen leidt bradykinine tot zwelling bij ontstekingsreacties. Een C1-esteraseremmer laat de zwelling weer afnemen. Deze remmer stopt de omzetting van factor XII en remt de activiteit van kallikreïne.$$, 'inline'),
  ('035d7275-de71-412c-b3fc-9f99f4c7932e', '750ffe83-9b39-4dff-9d23-8393c53598ff', $$onvolledig schema van de regulatie van weefselvloeistofvorming$$,
   $$biologie-vwo-2026-ii-moleculair-gereedschap-tegen-erfelijk-oedeem-context10.png$$,
   $$Hieronder is de regulatie die leidt tot de vorming van weefselvloeistof in een schema weergegeven. Het schema is niet compleet.$$, 'inline'),
  ('79e0c00a-d1f9-4547-8fa4-80083e55b581', '750ffe83-9b39-4dff-9d23-8393c53598ff', $$in de uitwerkbijlage staat hetzelfde schema$$,
   $$biologie-vwo-2026-ii-moleculair-gereedschap-tegen-erfelijk-oedeem-context11.png$$,
   $$In de uitwerkbijlage staat hetzelfde schema.$$, 'inline'),
  ('9492d607-03d8-4037-a841-cb6208439e80', '750ffe83-9b39-4dff-9d23-8393c53598ff', $$AON-therapie: enkelstrengs DNA remt translatie van het prekallikreïne-mRNA$$,
   $$biologie-vwo-2026-ii-moleculair-gereedschap-tegen-erfelijk-oedeem-context12.png$$,
   $$Sommige mensen maken geen prekallikreïne aan. Dit blijkt geen effect te hebben op hun gezondheid. Cohn kwam zo op het idee om patiënten met HAE-1 te behandelen door de productie van het prekallikreïne-eiwit te verhinderen. Hij ontwikkelde een speciaal stukje enkelstrengs DNA: een AON (antisense oligonucleotide). Na toediening bindt deze AON in het grondplasma van levercellen aan het mRNA voor prekallikreïne. Het DNA- mRNA-complex dat dan ontstaat, is het substraat voor een enzym dat het mRNA doorknipt. Door deze AON-therapie wordt de translatie geremd.$$, 'inline'),
  ('7aa23d7e-c598-4849-a46b-178672fec124', '750ffe83-9b39-4dff-9d23-8393c53598ff', $$coderende streng van het prekallikreïne-gen waarop de AON is gebaseerd$$,
   $$biologie-vwo-2026-ii-moleculair-gereedschap-tegen-erfelijk-oedeem-context13.png$$,
   $$Hieronder staat een deel van de coderende streng van het prekallikreïne- gen waarop de AON is gebaseerd. 5’- TGTTTGCCAAGAGACTTGGCA - 3’$$, 'inline'),
  ('c7c5c66d-2ed3-4a84-bc83-c93f6fe9be1c', '750ffe83-9b39-4dff-9d23-8393c53598ff', $$crispr-cas-therapie met liposomen, Cas9 en gids-RNA (afbeelding 2)$$,
   $$biologie-vwo-2026-ii-moleculair-gereedschap-tegen-erfelijk-oedeem-context14.png$$,
   $$Om HAE-1 effectiever te behandelen, ontwikkelde Cohn een therapie met behulp van de crispr-cas-techniek. De HAE-1-patiënt kreeg deze therapie door middel van een infuus in de bovenarm. De crispr-cas-techniek schakelt het gen voor prekallikreïne uit, waardoor de aanmaak van het eiwit niet meer mogelijk is. Hieronder staat een beschrijving van de techniek. Zie ook afbeelding 2. Het infuus bevat liposomen waarvoor alleen de levercellen receptoren hebben. De liposomen bevatten een stukje mRNA dat codeert voor het Cas9-eiwit (crispr-associated nuclease) en een stukje gids-RNA. Na opname door de cel wordt met het mRNA het Cas9-eiwit gevormd. Het gids-RNA leidt het eiwit vervolgens naar een specifieke plaats op het prekallikreïne-gen. Daar knipt het Cas9-eiwit het DNA door. De cel zal proberen de breuk in het DNA te herstellen. Hierbij ontstaan vaak mutaties waardoor er geen werkend prekallikreïne meer kan worden gevormd.
afbeelding 2$$, 'inline'),
  ('2318a9b1-b772-46e9-bf3a-94370ab9bd9d', '750ffe83-9b39-4dff-9d23-8393c53598ff', $$uitwerkbijlage: zelfde schema van de weefselvloeistofregulatie$$,
   $$biologie-vwo-2026-ii-moleculair-gereedschap-tegen-erfelijk-oedeem-context15.png$$,
   $$27$$, 'uitwerkbijlage'),
  ('4b247e9d-72d2-4ac0-8b69-b2119203d1dc', 'ec3c5fd5-229d-4261-9cc5-89be728b3b82', $$intro: onderzoek naar bedreiging van de flamingopopulatie op Bonaire$$,
   $$biologie-vwo-2026-ii-flamingos-op-bonaire-context1.png$$,
   $$De inwoners van Bonaire vinden vaak verdwaalde, zieke en dode flamingokuikens. Wetenschappers onderzochten of de flamingo-populatie (Caraïbische flamingo, Phoenicopterus ruber) op Bonaire in gevaar is.$$, 'inline'),
  ('dbd25e63-7b67-4aba-9280-5d535392e9df', 'ec3c5fd5-229d-4261-9cc5-89be728b3b82', $$Caraïbische flamingo''s: voedsel, nestbouw en ontwikkeling van kuikens (afbeelding 1, 2)$$,
   $$biologie-vwo-2026-ii-flamingos-op-bonaire-context2.png$$,
   $$Caraïbische flamingo’s filteren afbeelding 1 onder andere kleine garnaaltjes en schelpdiertjes uit het water en de modderige bodem. Dit voedsel bevat de carotenoïden die hun veren de roze kleur geven. Flamingo’s nestelen op open moddervlaktes in de buurt van de zee. Ze bouwen verhoogde nesten van modder (afbeelding 1).
afbeelding 2 Flamingo’s kruipen als witte, pluizige kuikens uit het ei (afbeelding 2). Na twee jaar ontwikkelen de jongvolwassen flamingo’s hun karakteristieke roze kleur.$$, 'inline'),
  ('c41de6a5-b655-4fbe-a889-527b3a88926c', 'ec3c5fd5-229d-4261-9cc5-89be728b3b82', $$verhoogd modderen nest beschermt en koelt het broedei$$,
   $$biologie-vwo-2026-ii-flamingos-op-bonaire-context3.png$$,
   $$Het verhoogde nest beschermt het ei tegen overstroming, en de vochtige modder koelt het ei af. Dat is gunstig voor de ontwikkeling van het embryo.$$, 'inline'),
  ('6e5fc25f-d26b-4294-bde8-c4b0ace089d4', 'ec3c5fd5-229d-4261-9cc5-89be728b3b82', $$op Bonaire ongeveer 1500 flamingo-broedparen$$,
   $$biologie-vwo-2026-ii-flamingos-op-bonaire-context4.png$$,
   $$Op Bonaire zijn ongeveer 1500 flamingo-broedparen. Experts vragen zich af of deze populatie groot genoeg is om op lange termijn te overleven.$$, 'inline'),
  ('6c37210e-3c11-4031-8495-7125f51c4856', 'ec3c5fd5-229d-4261-9cc5-89be728b3b82', $$flamingokuikens in een crèche; mogelijke oorzaken van verzwakte kuikens$$,
   $$biologie-vwo-2026-ii-flamingos-op-bonaire-context5.png$$,
   $$Een flamingokuiken blijft een paar dagen op het nest. Daarna leeft het enkele weken in een grote groep kuikens: een crèche. De crèche wordt bewaakt door volwassen vogels. De laatste jaren zijn er steeds vaker eenzame, verzwakte kuikens gevonden. Mogelijk komt dit doordat de kuikens door verstoring de crèche hebben verlaten. Het kan ook veroorzaakt worden doordat in de zoutmeren en baaien waar de flamingo’s leven, eutrofiëring optreedt. Flamingo-ouders kunnen daardoor mogelijk niet voldoende voedsel vinden.$$, 'inline'),
  ('8d6f5dc7-50a6-4630-9465-fe1b72f1bbd8', 'ec3c5fd5-229d-4261-9cc5-89be728b3b82', $$wiskundig populatiemodel met leeftijdsklassen en overlevingskansen (afbeelding 3)$$,
   $$biologie-vwo-2026-ii-flamingos-op-bonaire-context6.png$$,
   $$Onderzoekers wilden weten of de grote sterfte van kuikens een bedreiging is voor de populatie flamingo’s op Bonaire. Met een wiskundig model onderzochten ze de impact van de sterfte van de kuikens op de populatiedynamiek. In afbeelding 3 is het model grafisch weergegeven. De cirkels geven de leeftijdsklassen weer van 0 tot en met 5 jaar, en de volwassen flamingo’s (A). De waardes bij de pijlen tussen de bolletjes zijn de overlevingskansen per jaar. De vetgedrukte waarde is de voortplantingscapaciteit: het aantal kuikens dat per jaar wordt geboren per individu van een bepaalde leeftijdsklasse.
afbeelding 3$$, 'inline'),
  ('3738cd53-6e54-4a6c-9955-41d4871e67a7', 'ec3c5fd5-229d-4261-9cc5-89be728b3b82', $$gegevens over overlevingskansen en voortplanting van de flamingosoort$$,
   $$biologie-vwo-2026-ii-flamingos-op-bonaire-context7.png$$,
   $$Hieronder staan gegevens van de flamingosoort die nestelt op Bonaire.
1 De overlevingskans van een volwassen flamingo is groter dan die van een flamingokuiken.
2 Een flamingo wordt maximaal 43 jaar oud.
3 Een flamingo plant zich meestal pas voort vanaf het 6e levensjaar.$$, 'inline'),
  ('2d646c37-bc30-4383-94b5-ef1207ffe52e', 'ec3c5fd5-229d-4261-9cc5-89be728b3b82', $$populatiegroeimodel: onbegrensde groei (periode P) en afvlakking (periode Q) (afbeelding 4)$$,
   $$biologie-vwo-2026-ii-flamingos-op-bonaire-context8.png$$,
   $$De onderzoekers concludeerden dat de hoge sterfte onder flamingokuikens geen grote bedreiging vormt voor de populatie op Bonaire. Met het model berekenden ze een populatiegroeisnelheid van 1,1. Dit betekent dat de populatie elk jaar met 10 procent toeneemt. In afbeelding 4 zie je dat de groei volgens dit model de eerste jaren (periode P) onbegrensd is. Na verloop van tijd zal de groeicurve afvlakken, omdat de groei begrensd raakt (periode Q).
afbeelding 4$$, 'inline');

